CREATE TABLE "College" (id text PRIMARY KEY, name text NOT NULL, "shortName" text NOT NULL, city text NOT NULL, state text NOT NULL, country text NOT NULL DEFAULT 'India', aliases text[] NOT NULL DEFAULT '{}', "verifiedDomains" text[] NOT NULL DEFAULT '{}', active boolean NOT NULL DEFAULT true);
CREATE INDEX "College_country_state_city_idx" ON "College" (country,state,city);
CREATE INDEX "College_aliases_idx" ON "College" USING gin(aliases);
CREATE TABLE "TaxonomyAlias" (field text NOT NULL, alias text NOT NULL, label text NOT NULL, PRIMARY KEY(field,alias));
CREATE TABLE "RecommendationSkillLink" (kind text NOT NULL, source text NOT NULL, target text NOT NULL, PRIMARY KEY(kind,source,target));
CREATE TABLE "RecommendationDocument" (kind text NOT NULL CHECK(kind IN ('PROFILE','IDEA','EVENT')), "targetId" text NOT NULL, "sourceHash" text NOT NULL, skills text[] NOT NULL DEFAULT '{}', interests text[] NOT NULL DEFAULT '{}', "lookingFor" text[] NOT NULL DEFAULT '{}', inferred jsonb NOT NULL DEFAULT '{}', embedding double precision[] NOT NULL DEFAULT '{}', "embeddingModel" text NOT NULL DEFAULT '', "updatedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(kind,"targetId"));
CREATE INDEX "RecommendationDocument_skills_idx" ON "RecommendationDocument" USING gin(skills);
CREATE INDEX "RecommendationDocument_interests_idx" ON "RecommendationDocument" USING gin(interests);
CREATE INDEX "RecommendationDocument_lookingFor_idx" ON "RecommendationDocument" USING gin("lookingFor");
CREATE TABLE "RecommendationJob" (kind text NOT NULL CHECK(kind IN ('PROFILE','IDEA','EVENT')), "targetId" text NOT NULL, version integer NOT NULL DEFAULT 1, attempts integer NOT NULL DEFAULT 0, "availableAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "lockedUntil" timestamp(3), "lockToken" text, "lastError" text, PRIMARY KEY(kind,"targetId"));
CREATE INDEX "RecommendationJob_availableAt_lockedUntil_idx" ON "RecommendationJob" ("availableAt","lockedUntil");
CREATE TABLE "RecommendationInteraction" ("userId" text NOT NULL REFERENCES "User"(id) ON DELETE CASCADE, "targetType" text NOT NULL CHECK("targetType" IN ('PROFILE','IDEA','EVENT')), "targetId" text NOT NULL, action text NOT NULL, day date NOT NULL, "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY("userId","targetType","targetId",action,day));
CREATE INDEX "RecommendationInteraction_userId_targetType_createdAt_idx" ON "RecommendationInteraction" ("userId","targetType","createdAt");
CREATE INDEX "RecommendationInteraction_createdAt_idx" ON "RecommendationInteraction" ("createdAt");
ALTER TABLE "College" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TaxonomyAlias" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "RecommendationSkillLink" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "RecommendationDocument" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "RecommendationJob" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "RecommendationInteraction" ENABLE ROW LEVEL SECURITY;
-- No browser policies: the existing trusted Prisma backend owns all access.
CREATE FUNCTION fc_key(value text) RETURNS text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$ SELECT regexp_replace(lower(trim(value)), '[^a-z0-9]+', '', 'g') $$;
CREATE FUNCTION fc_normalize(field_name text, vals text[]) RETURNS text[] LANGUAGE sql STABLE AS $$
 SELECT COALESCE(array_agg(DISTINCT COALESCE(a.label, trim(v))), '{}') FROM unnest(vals) v LEFT JOIN "TaxonomyAlias" a ON a.field=field_name AND a.alias=fc_key(v) WHERE trim(v)<>''
$$;
CREATE FUNCTION fc_link(link_kind text, vals text[]) RETURNS text[] LANGUAGE sql STABLE AS $$ SELECT COALESCE(array_agg(DISTINCT target),'{}') FROM "RecommendationSkillLink" WHERE kind=link_kind AND source=ANY(vals) $$;
CREATE FUNCTION fc_overlap(a text[], b text[]) RETURNS double precision LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$ SELECT count(DISTINCT v)::double precision FROM unnest(a) v WHERE v=ANY(b) $$;
CREATE FUNCTION fc_cosine(a double precision[], b double precision[]) RETURNS double precision LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $$
 SELECT CASE WHEN cardinality(a)=cardinality(b) AND cardinality(a)>0 THEN COALESCE(sum(x*y)/NULLIF(sqrt(sum(x*x))*sqrt(sum(y*y)),0),0) ELSE 0 END FROM unnest(a,b) AS v(x,y)
$$;
CREATE FUNCTION fc_college(value text) RETURNS text LANGUAGE sql STABLE AS $$ SELECT COALESCE((SELECT id FROM "College" c WHERE fc_key(c.name)=fc_key(value) OR fc_key(c."shortName")=fc_key(value) OR EXISTS(SELECT 1 FROM unnest(c.aliases) a WHERE fc_key(a)=fc_key(value)) ORDER BY id LIMIT 1),fc_key(value)) $$;
-- Trigger only tracks public recommendation fields. No names, contact URLs or private data.
CREATE FUNCTION fc_enqueue() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE k text; payload jsonb; old_payload jsonb;
BEGIN
 k := CASE TG_TABLE_NAME WHEN 'User' THEN 'PROFILE' WHEN 'Idea' THEN 'IDEA' ELSE 'EVENT' END;
 IF TG_OP='DELETE' THEN
   DELETE FROM "RecommendationDocument" WHERE kind=k AND "targetId"=OLD.id;
   DELETE FROM "RecommendationJob" WHERE kind=k AND "targetId"=OLD.id;
   DELETE FROM "RecommendationInteraction" WHERE "targetType"=k AND "targetId"=OLD.id;
   RETURN OLD;
 END IF;
 IF k='PROFILE' THEN
   payload:=jsonb_build_array(NEW.bio,NEW.skills,NEW.interests,NEW.domains,NEW."lookingFor",NEW.college,NEW.city,NEW."graduationYear");
   IF TG_OP='UPDATE' THEN old_payload:=jsonb_build_array(OLD.bio,OLD.skills,OLD.interests,OLD.domains,OLD."lookingFor",OLD.college,OLD.city,OLD."graduationYear"); END IF;
 ELSIF k='IDEA' THEN
   payload:=jsonb_build_array(NEW.title,NEW.description,NEW.category,NEW.skills,NEW.tags);
   IF TG_OP='UPDATE' THEN old_payload:=jsonb_build_array(OLD.title,OLD.description,OLD.category,OLD.skills,OLD.tags); END IF;
 ELSE
   payload:=jsonb_build_array(NEW.title,NEW.description,NEW.category);
   IF TG_OP='UPDATE' THEN old_payload:=jsonb_build_array(OLD.title,OLD.description,OLD.category); END IF;
 END IF;
 IF payload IS NOT DISTINCT FROM old_payload THEN RETURN NEW; END IF;
 DELETE FROM "RecommendationDocument" WHERE kind=k AND "targetId"=NEW.id;
 ON CONFLICT(kind,"targetId") DO UPDATE SET version="RecommendationJob".version+1, attempts=0,"availableAt"=CURRENT_TIMESTAMP,"lockedUntil"=NULL,"lockToken"=NULL,"lastError"=NULL;
 RETURN NEW;
END $$;
CREATE TRIGGER fc_profile_changed AFTER INSERT OR UPDATE OR DELETE ON "User" FOR EACH ROW EXECUTE FUNCTION fc_enqueue();
CREATE TRIGGER fc_idea_changed AFTER INSERT OR UPDATE OR DELETE ON "Idea" FOR EACH ROW EXECUTE FUNCTION fc_enqueue();
CREATE TRIGGER fc_event_changed AFTER INSERT OR UPDATE OR DELETE ON "Event" FOR EACH ROW EXECUTE FUNCTION fc_enqueue();
-- Helpers are only for the backend role. No public RPC execution surface.
REVOKE ALL ON FUNCTION fc_key(text),fc_normalize(text,text[]),fc_link(text,text[]),fc_overlap(text[],text[]),fc_cosine(double precision[],double precision[]),fc_college(text),fc_enqueue() FROM PUBLIC;

